#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    cin >> n >> k;

    vector<int> b(k);
    for (int &x : b) cin >> x;
    sort(b.begin(), b.end());

    int two = 2 * n;
    int four = n;
    int single = 0;
    bool ans = true;

    for (int i = 0; i < k && ans; ++i) {
        while (b[i] > 0 && ans) {
            int take = min(8, b[i]);
            if (take & 1) ++take;

            bool placed = true;

            if (take == 2) {
                if (two > 0) {
                    --two;
                } else if (four > 0) {
                    --four;
                    ++single;
                } else {
                    placed = false;
                }
            } else if (take == 4) {
                if (four > 0) {
                    --four;
                } else if (two > 1) {
                    two -= 2;
                } else {
                    placed = false;
                }
            } else if (take == 6) {
                if (two > 1 && four > 0) {
                    --two;
                    --four;
                } else if (two > 2) {
                    two -= 3;
                } else if (four > 1) {
                    four -= 2;
                    ++single;
                } else {
                    placed = false;
                }
            } else {
                if (four > 1) {
                    four -= 2;
                } else if (four > 0 && two > 1) {
                    --four;
                    two -= 2;
                } else if (two > 3) {
                    two -= 4;
                } else {
                    placed = false;
                }
            }

            if (placed) {
                b[i] -= take;
                continue;
            }

            int need = take;
            if (b[i] & 1) --need;
            int consumed = need;

            int usedFour = min(four, need / 4);
            four -= usedFour;
            need -= usedFour * 4;

            int usedTwo = min(two, need / 2);
            two -= usedTwo;
            need -= usedTwo * 2;

            if (single >= need) {
                single -= need;
                b[i] -= consumed;
            } else {
                ans = false;
            }
        }
    }

    cout << (ans ? "YES" : "NO");
    return 0;
}

